#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    std::vector<std::complex<double>> buffer(n);

    for (std::size_t width = 1; width < n; width *= 2) {
        const std::size_t block = 2 * width;

        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t left = 0; left < static_cast<std::ptrdiff_t>(n); left += static_cast<std::ptrdiff_t>(block)) {
            const std::size_t l = static_cast<std::size_t>(left);
            const std::size_t mid = std::min(l + width, n);
            const std::size_t right = std::min(l + block, n);

            std::size_t i = l;
            std::size_t j = mid;
            std::size_t k = l;

            while (i < mid && j < right) {
                const double mi = std::norm(x[i]);
                const double mj = std::norm(x[j]);

                if (mi <= mj) {
                    buffer[k++] = x[i++];
                } else {
                    buffer[k++] = x[j++];
                }
            }

            while (i < mid) {
                buffer[k++] = x[i++];
            }

            while (j < right) {
                buffer[k++] = x[j++];
            }
        }

        x.swap(buffer);
    }
}
